package com.quickcart.service;
import com.quickcart.entity.*; import com.quickcart.repository.*; import com.quickcart.dto.*; import com.quickcart.exception.ApiException; import org.springframework.http.HttpStatus; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import java.util.*;
@Service public class OrderService {final OrderRepository orders;final OrderItemRepository items;final ProductRepository products;final CustomerRepository customers;final AddressRepository addresses; OrderService(OrderRepository o,OrderItemRepository i,ProductRepository p,CustomerRepository c,AddressRepository a){orders=o;items=i;products=p;customers=c;addresses=a;}
@Transactional public CustomerOrder create(OrderRequest r){if(r.items()==null||r.items().isEmpty())throw new ApiException(HttpStatus.BAD_REQUEST,"Cart is empty");Customer c=customers.findById(r.customerId()==null?0:r.customerId()).orElseGet(()->customers.save(new Customer(null,"Guest Customer","","",null,null)));Address a=r.addressId()==null?null:addresses.findById(r.addressId()).orElseThrow(()->new ApiException(HttpStatus.NOT_FOUND,"Address not found"));double sub=0;CustomerOrder o=new CustomerOrder();o.setOrderNumber("ZP"+System.currentTimeMillis());o.setCustomer(c);o.setPaymentMethod(PaymentMethod.COD);o.setPaymentStatus(PaymentStatus.PENDING);o.setOrderStatus(OrderStatus.CREATED);o.setDiscount(0);o.setDeliveryFee(0);o.setCreatedAt(java.time.LocalDateTime.now());o.setUpdatedAt(java.time.LocalDateTime.now());o.setDeliveryAddressSnapshot(a==null?"Hyderabad":String.join(", ",a.getHouse(),a.getStreet(),a.getArea(),a.getCity()+" - "+a.getPincode()));o=orders.save(o);for(OrderItemRequest ir:r.items()){Product p=products.findById(ir.productId()).orElseThrow(()->new ApiException(HttpStatus.NOT_FOUND,"Product not found: "+ir.productId()));if(!p.isAvailable()||p.getStockQuantity()<ir.quantity())throw new ApiException(HttpStatus.CONFLICT,"Product unavailable or out of stock: "+p.getName());double line=p.getSellingPrice()*ir.quantity();sub+=line;p.setStockQuantity(p.getStockQuantity()-ir.quantity());if(p.getStockQuantity()==0)p.setAvailable(false);products.save(p);items.save(new OrderItem(null,o,p,p.getName(),p.getSellingPrice(),ir.quantity(),line));}double fee=sub>=499?0:39;o.setSubtotal(sub);o.setDeliveryFee(fee);o.setTotalAmount(sub+fee);return orders.save(o);}
public List<CustomerOrder> list(Long cid){return orders.findByCustomerIdOrderByCreatedAtDesc(cid);} public CustomerOrder one(Long id){return orders.findById(id).orElseThrow(()->new ApiException(HttpStatus.NOT_FOUND,"Order not found"));} }
